{
  "claims": [
    {
      "claim": "Never search for card numbers in logs as they are never logged and searching for card-like regexes triggers internal security audits.",
      "page": "howto-trace-a-refund"
    },
    {
      "claim": "Narrow the search window in the log search tool to a specific 2- to 4-hour window around the cancellation or support ticket.",
      "page": "howto-trace-a-refund"
    },
    {
      "claim": "A normal refund lifecycle in the payments service produces three distinct log lines in index sorrel-prod-*: 'refund requested', 'refund sent', and 'refund settled'.",
      "page": "howto-trace-a-refund"
    },
    {
      "claim": "To locate the payment reference (ref) from a booking_id, search the sorrel-prod-* index with `service=payments booking_id=\"<booking_id>\"`, find the 'refund requested' line, and copy the ref value.",
      "page": "howto-trace-a-refund"
    },
    {
      "claim": "To trace outbound dispatch to stripe, run `service=payments msg=\"refund sent\" ref=\"<ref>\"` to see when the instruction reached stripe and inspect the HTTP response status.",
      "page": "howto-trace-a-refund"
    },
    {
      "claim": "If 'refund sent' returned HTTP 200, Stripe acknowledged the instruction; if HTTP 4xx/5xx, check provider_ms, provider error messages, and status.stripe.com; if no result is found, check for queue deadlocks or database issues.",
      "page": "howto-trace-a-refund"
    },
    {
      "claim": "To check webhook settlement, run `service=payments msg=\"refund settled\" ref=\"<ref>\"`.",
      "page": "howto-trace-a-refund"
    },
    {
      "claim": "If the 'refund settled' line exists, the cycle is complete, and any delay is due to inter-bank processing delays (typically 5–10 business days).",
      "page": "howto-trace-a-refund"
    },
    {
      "claim": "If no 'refund settled' line appears, it is normal if 'refund sent' was fewer than 6 hours ago; otherwise check webhook health on the Sorrel / payments dashboard or query `service=payments msg=\"webhook\" outcome=retry ref=\"<ref>\"`.",
      "page": "howto-trace-a-refund"
    },
    {
      "claim": "If one reference shows two 'sent' lines, money may have moved twice: stop the investigation immediately and page Mei.",
      "page": "howto-trace-a-refund"
    }
  ],
  "not_in_pages": []
}

